export const sequenceWeightCurveContract={field:'optional section.weightCurve [{time,value,interpolation?}]; first time0, ordered unique times0..86400, value0..1, linear(default)|step|auto|clampedAuto|user|break with bounded scalar cubic/weighted/vertical controls; constant endpoint extension; optional keys beyond current section end are retained',weight:'effective child weight = parent * child asset * static section weight * section curve value at parentTime-section.start; curve uses section clock, independently of source loop/reverse/timeWarp',behavior:'normalized peers mix using these weights; lone nonzero normalized owner stays full strength, so this is relative layer mixing, not standalone opacity/audio fade; events/audio/discrete fields keep existing rules',trim:'front trim inserts the original boundary value/interpolation at new time0 and rebases remaining keys, retaining their source curve; extending left holds the original first value',control:'root SetWeight/SetBlendMode recomputes curve factor at current parent time; runtime.sequenceTree exposes authored static weight and instantaneous sectionCurveWeight; paused seek uses same evaluator',budget:'existing sequence keyBudget includes all section weight keys; per-curve limit uses existing65536 per-track rule; property list pages32; no object-count cap',cost:'no curve means constant1; weak prepared binary lookup directly in immutable key arrays, no per-frame sort or key copies; reweight only changed owners using existing child traversal; no timer/worker/GPU resource',remaining:['standalone baseline-filled/additive blending','animation mixer action weights','cubic AudioParam scheduling and pitch-preserving time stretch']};
